const headers = $json.headers ?? {};
const tokenHeader = headers['x-govhub-token'] || headers['X-GOVHUB-TOKEN'];
const allowed = String($env.GOVHUB_TOKENS || '').split(',').map((v) => v.trim()).filter(Boolean);
if (!tokenHeader || !allowed.includes(String(tokenHeader).trim())) {
  return [{ json: { ok: false, statusCode: 401, status: 'unauthorized', error_code: 'AUTH_INVALID_TOKEN', message: 'invalid token' } }];
}
const input = { ...($json.query ?? {}), ...($json.body ?? {}) };
const repo_key = input.repo_key ? String(input.repo_key).trim() : '';
const agent_id = input.agent_id ? String(input.agent_id).trim() : '';
if (!repo_key || !agent_id) {
  return [{ json: { ok: false, statusCode: 400, status: 'invalid_request', error_code: 'MISSIONS_NEXT_INVALID_REQUEST', message: 'repo_key and agent_id are required' } }];
}
const esc = (value) => String(value).replace(/'/g, "''");
return [{ json: { ok: true, repo_key, repo_key_sql: esc(repo_key), agent_id, agent_id_sql: esc(agent_id), lock_ttl_seconds: 900 } }];
